        "sourceAudioSha256": "bb1b47a8eba7d47ac66a778035cd8a639835a2010a689581280ff79dc09ec5d9",
        "sourceAudioTextSha256": "b5381b72a5a0f591017e81a18803537a571a978f5c82599801e506804bcc416a",
