        "sourceImageSha256": "872e1722e1dbd912ec32232cbd5c88c0e89c0d98b70af2cbc4978c5c0629492d",
        "imageWidth": 550,
        "imageHeight": 546,
        "audioFile": "audio/10-96a837ccb206dc32.mp3",
