        "imageWidth": 465,
        "imageHeight": 480,
        "audioFile": "audio/02-064ae606f35fb38a.mp3",
        "sourceAudio": "https://vanesacoding.github.io/say-it-today/books/library/0117/audio/02-064ae606f35fb38a.mp3",
